const body = $json.body ?? {};

const questions = [
  "Kalau lagi punya waktu luang, kamu lebih suka ngapain?",
  "Pelajaran atau kegiatan apa di sekolah yang menurutmu paling gampang atau paling kamu suka, dan kenapa?",
  "Kalau kamu kerja kelompok, biasanya kamu paling sering kebagian tugas apa?",
  "Kamu lebih suka kerja sendirian fokus di depan komputer/data, kerja tim bikin sesuatu baru, atau ketemu banyak orang tiap hari?",
  "Kalau ada tugas yang harus teliti banget, gimana perasaanmu — semangat, biasa aja, atau bosen?"
];

const jurusanInfo = [
  { kode: "PPLG", nama: "Pengembangan Perangkat Lunak dan Gim", deskripsi: "suka logika, komputer, coding, analisis sistem, dan bikin aplikasi/gim." },
  { kode: "Akuntansi", nama: "Akuntansi dan Keuangan Lembaga", deskripsi: "teliti, suka angka, pembukuan, pengelolaan keuangan, dan data terstruktur." },
  { kode: "Perhotelan", nama: "Perhotelan", deskripsi: "ramah, suka bertemu orang, pelayanan tamu, front office, dan kerja tim." }
];

const answers = [body.jawaban_1, body.jawaban_2, body.jawaban_3, body.jawaban_4, body.jawaban_5];

const questionBlock = questions.map((q, i) => `Pertanyaan ${i + 1}: ${q}\nJawaban ${i + 1}: ${answers[i] ?? "(kosong)"}`).join("\n\n");

const jurusanBlock = jurusanInfo.map((j) => `- ${j.kode} (${j.nama}): ${j.deskripsi}`).join("\n");

const prompt = [
  "Kamu adalah asisten rekomendasi jurusan SMK. Analisis jawaban siswa berikut lalu tentukan jurusan paling cocok di antara PPLG, Akuntansi, dan Perhotelan.",
  "",
  "JURUSAN YANG TERSEDIA:",
  jurusanBlock,
  "",
  "JAWABAN SISWA:",
  questionBlock,
  "",
  "TUGAS:",
  "1. Analisis minat, kepribadian, dan gaya kerja siswa dari jawabannya.",
  "2. Pilih SATU jurusan paling cocok.",
  "3. Beri persentase kecocokan untuk KETIGA jurusan (bilangan bulat 0-100, total = 100).",
  "4. Tulis alasan 2-3 kalimat dalam Bahasa Indonesia yang natural.",
  "",
  "OUTPUT: Balas HANYA dengan JSON valid tanpa markdown, persis format ini:",
  '{ "nama_jurusan": "PPLG" | "Akuntansi" | "Perhotelan", "alasan": "string", "persentase_akuntansi": number, "persentase_pplg": number, "persentase_hotel": number }'
].join("\n");

const requestBody = {
  model: "nvidia/GANTI_DENGAN_NAMA_MODEL_NEMOTRON",
  messages: [
    { role: "system", content: "Kamu adalah asisten rekomendasi jurusan SMK. Hanya keluarkan JSON valid, tanpa teks lain." },
    { role: "user", content: prompt }
  ],
  temperature: 0.3
};

return [{ prompt, requestBody: JSON.stringify(requestBody) }];

const aiText = $json?.choices?.[0]?.message?.content ?? "";

const clamp = (value) => Math.max(0, Math.min(100, Math.round(Number(value) || 0)));

let parsed = null;
if (aiText) {
  try {
    parsed = JSON.parse(aiText);
  } catch {
    const match = aiText.match(/\{[\s\S]*\}/);
    if (match) {
      try { parsed = JSON.parse(match[0]); } catch { parsed = null; }
    }
  }
}

const validJurusan = ["PPLG", "Akuntansi", "Perhotelan"];
const namaJurusan = parsed?.nama_jurusan && validJurusan.includes(parsed.nama_jurusan) ? parsed.nama_jurusan : "PPLG";

return [{
  nama_jurusan: namaJurusan,
  alasan: parsed?.alasan || "Berdasarkan jawabanmu, PPLG dinilai paling sesuai dengan minat dan gaya belajarmu.",
  persentase_akuntansi: parsed ? clamp(parsed.persentase_akuntansi) : 33,
  persentase_pplg: parsed ? clamp(parsed.persentase_pplg) : 34,
  persentase_hotel: parsed ? clamp(parsed.persentase_hotel) : 33
}];
